"use client";

import { useEffect, useRef, type HTMLAttributes, type ReactNode } from "react";

export function Sheet({ open, onOpenChange, children, side = "right", className = "" }: { open: boolean; onOpenChange: (open: boolean) => void; children: ReactNode; side?: "left" | "right"; className?: string }) { const ref = useRef<HTMLDialogElement>(null); useEffect(() => { const node = ref.current; if (open && node && !node.open) node.showModal(); if (!open && node?.open) node.close(); }, [open]); return <dialog ref={ref} className={`${side === "right" ? "co-ms-auto" : "co-me-auto"} co-h-full co-max-h-none co-w-[min(28rem,92vw)] co-max-w-none co-rounded-none co-border co-border-black/15 co-bg-white co-p-6 co-shadow-xl backdrop:co-bg-black/55 ${className}`.trim()} onCancel={() => onOpenChange(false)} onClose={() => onOpenChange(false)}>{children}</dialog>; }
export function SheetHeader({ className = "", ...props }: HTMLAttributes<HTMLDivElement>) { return <div className={`co-grid co-gap-2 ${className}`.trim()} {...props} />; }
export function SheetFooter({ className = "", ...props }: HTMLAttributes<HTMLDivElement>) { return <div className={`co-mt-6 co-flex co-justify-end co-gap-2 ${className}`.trim()} {...props} />; }
